// Sprint 3: LandRegistry with the real Groth16Verifier and real proofs.
// Fixtures (PLAN.md I6) are generated by Maneesh's `register.js --dry-run`
// on his machine and committed under test/fixtures/. Nothing is proved here.
const { expect } = require("chai");
const { ethers } = require("hardhat");
const { loadFixture } = require("@nomicfoundation/hardhat-network-helpers");

const A = require("./fixtures/A.json");
const C = require("./fixtures/C_after_A.json");
const B_OVERLAP = require("./fixtures/B_overlap.json");

const toBig = (x) => (Array.isArray(x) ? x.map(toBig) : BigInt(x));

// Turn a fixture into registerParcel arguments (after `owner`).
function args(fx, overrides = {}) {
  const f = { ...fx, ...overrides };
  return [toBig(f.a), toBig(f.b), toBig(f.c), toBig(f.pubSignals), toBig(f.coarseCells), f.metadataURI];
}

async function deploy() {
  const [deployer, owner, other, stranger] = await ethers.getSigners();
  const verifier = await (await ethers.getContractFactory("Groth16Verifier")).deploy();
  const reg = await (await ethers.getContractFactory("LandRegistry"))
    .deploy(await verifier.getAddress(), deployer.address);
  await reg.grantRole(await reg.REGISTRAR_ROLE(), deployer.address);
  return { reg, verifier, registrar: deployer, owner, other, stranger };
}

async function deployWithA() {
  const ctx = await deploy();
  await ctx.reg.connect(ctx.registrar).registerParcel(ctx.owner.address, ...args(A));
  return ctx;
}

describe("LandRegistry end to end (real Groth16Verifier, real proofs)", function () {
  it("fixtures chain: C was proved on the root A produces", function () {
    expect(A.pubSignals[0]).to.equal("0");
    expect(C.pubSignals[0]).to.equal(A.pubSignals[1]);
  });

  it("1. A registers: root becomes A's newRoot, token 1 minted, event emitted", async function () {
    const { reg, registrar, owner } = await loadFixture(deploy);
    const [oldRoot, newRoot, commitment] = toBig(A.pubSignals);
    await expect(reg.connect(registrar).registerParcel(owner.address, ...args(A)))
      .to.emit(reg, "ParcelRegistered")
      .withArgs(1n, owner.address, commitment, oldRoot, newRoot);
    expect(await reg.occupiedRoot()).to.equal(newRoot);
    expect(await reg.ownerOf(1)).to.equal(owner.address);
    expect(await reg.commitmentUsed(commitment)).to.equal(true);
    const [storedCommitment, cells, uri] = await reg.getParcel(1);
    expect(storedCommitment).to.equal(commitment);
    expect(cells).to.deep.equal(toBig(A.coarseCells));
    expect(uri).to.equal(A.metadataURI);
  });

  it("2. replaying A's proof after A reverts with StaleRoot", async function () {
    const { reg, registrar, owner } = await loadFixture(deployWithA);
    await expect(reg.connect(registrar).registerParcel(owner.address, ...args(A)))
      .to.be.revertedWithCustomError(reg, "StaleRoot");
  });

  it("3. C registers after A: root becomes C's newRoot, token 2 minted", async function () {
    const { reg, registrar, other } = await loadFixture(deployWithA);
    const [oldRoot, newRoot, commitment] = toBig(C.pubSignals);
    await expect(reg.connect(registrar).registerParcel(other.address, ...args(C)))
      .to.emit(reg, "ParcelRegistered")
      .withArgs(2n, other.address, commitment, oldRoot, newRoot);
    expect(await reg.occupiedRoot()).to.equal(newRoot);
    expect(await reg.ownerOf(2)).to.equal(other.address);
  });

  it("4. A's proof with one public signal changed reverts with InvalidProof", async function () {
    const { reg, registrar, owner } = await loadFixture(deploy);
    // Change newRoot (index 1). Changing oldRoot would hit StaleRoot first.
    const tampered = [...A.pubSignals];
    tampered[1] = (BigInt(tampered[1]) + 1n).toString();
    await expect(reg.connect(registrar).registerParcel(owner.address, ...args(A, { pubSignals: tampered })))
      .to.be.revertedWithCustomError(reg, "InvalidProof");
    expect(await reg.occupiedRoot()).to.equal(0n);
  });

  it("4b. A's proof with the commitment changed also reverts with InvalidProof", async function () {
    const { reg, registrar, owner } = await loadFixture(deploy);
    const tampered = [...A.pubSignals];
    tampered[2] = (BigInt(tampered[2]) + 1n).toString();
    await expect(reg.connect(registrar).registerParcel(owner.address, ...args(A, { pubSignals: tampered })))
      .to.be.revertedWithCustomError(reg, "InvalidProof");
  });

  it("5. a valid proof sent by a non-registrar reverts", async function () {
    const { reg, owner, stranger } = await loadFixture(deploy);
    await expect(reg.connect(stranger).registerParcel(owner.address, ...args(A)))
      .to.be.revertedWithCustomError(reg, "AccessControlUnauthorizedAccount")
      .withArgs(stranger.address, await reg.REGISTRAR_ROLE());
    expect(await reg.occupiedRoot()).to.equal(0n);
  });

  it("6. B_overlap.json: the registrar refused B as an overlap with A", function () {
    expect(B_OVERLAP.status).to.equal("overlap");
    expect(B_OVERLAP.overlaps).to.include("A");
  });
});
